from __future__ import annotations

import os
from typing import Iterable, Mapping, Any

from google.cloud import pubsub_v1


def publish_batch(
    project_id: str,
    topic_id: str,
    messages: Iterable[Mapping[str, Any]],
) -> list[str]:
    publisher = pubsub_v1.PublisherClient()
    topic_path = publisher.topic_path(project_id, topic_id)

    futures = []
    for message in messages:
        data = message.get("data", b"")
        if isinstance(data, str):
            data = data.encode("utf-8")
        elif not isinstance(data, (bytes, bytearray)):
            data = str(data).encode("utf-8")

        attributes = {
            str(k): str(v)
            for k, v in (message.get("attributes") or {}).items()
        }

        ordering_key = message.get("ordering_key")
        if ordering_key is not None:
            attributes["ordering_key"] = str(ordering_key)

        future = publisher.publish(topic_path, bytes(data), **attributes)
        futures.append(future)

    return [future.result() for future in futures]


if __name__ == "__main__":
    project_id = os.environ["GOOGLE_CLOUD_PROJECT"]
    topic_id = os.environ["PUBSUB_TOPIC_ID"]

    batch = [
        {
            "data": "first message",
            "attributes": {"id": "msg-1", "source": "app"},
        },
        {
            "data": "second message",
            "attributes": {"id": "msg-2", "type": "event"},
        },
    ]

    message_ids = publish_batch(project_id, topic_id, batch)
    print(message_ids)
